/// <reference types="vite/client" />

// The song catalogue, generated by plugins/ableton.ts from songs/*/song.toml.
declare module 'virtual:songs' {
  export interface Section {
    name: string;
    /** 1-based and inclusive. */
    start_bar: number;
    end_bar: number;
  }
  export interface SongMeta {
    slug: string;
    title: string;
    /** MIDI key -> instrument name (kick, snare, hihat_closed, ...). */
    map: Record<number, string>;
    /** The `[[section]]` blocks, in the order they are written. */
    sections: Section[];
    /** Those blocks as one string, so a take can be pinned to them. */
    sectionsHash: string;
    author?: { als: string; track?: string };
    /**
     * Which untracked media is on disk: `mix` is the clock (without it the
     * song cannot play), `video` the picture the notation sits over.
     */
    media: { mix: boolean; video: boolean };
  }
  const songs: SongMeta[];
  export default songs;
}

// kit.toml's `[input]`, generated by plugins/practice.ts: what the module you
// hit sends. Not the same numbering as a song's `[midi_map]` -- see kit.toml.
declare module 'virtual:kit' {
  export interface KitInput {
    /** Substring of the MIDI port name to open by default. */
    port: string;
    /** Module note number -> instrument name. */
    note: Record<number, string>;
    /** Groups of instruments that are one drum in different states. */
    same_drum: string[][];
  }
  const input: KitInput;
  export default input;
}
